    elif op == 'pattern_bind':
        env[args[0]] = value
        return _bind_pattern(args[1], value, env)
    elif op=='pattern_array':
        if not isinstance(value,list): return False
        for i,p in enumerate(args[0]):
            if not _bind_pattern(p, value[i] if i<len(value) else None, env): return False
        return True
    elif op=='pattern_object':
        if not isinstance(value,dict): return False
        for key,p in args[0]:
            if isinstance(key, Node):
                key = _one(key, value, env)
            if not _bind_pattern(p, value.get(key), env): return False
        return True
    return False

def _initialize_pattern(pattern, env):
    op, args = pattern.operation, pattern.arguments
    if op == 'pattern_var': env.setdefault(args[0], None)
    elif op == 'pattern_bind':
        env.setdefault(args[0], None); _initialize_pattern(args[1], env)
    elif op == 'pattern_array':
        for item in args[0]: _initialize_pattern(item, env)
    elif op == 'pattern_object':
        for _, item in args[0]: _initialize_pattern(item, env)
    elif op == 'pattern_alt':
        _initialize_pattern(args[0], env); _initialize_pattern(args[1], env)

        _initialize_pattern(args[0], env); _initialize_pattern(args[1], env)

def _one(node, value, env):
    vals=list(_node(node,value,env)); return vals[0] if vals else None
def _truth(x): return x is not None and x is not False
def _index(v,k):
    if v is None:
        return None
    if isinstance(v,dict): return v.get(str(k))
    if isinstance(v,list):
        if isinstance(k, float) and math.isnan(k):
            return None
        if isinstance(k, bool) or not isinstance(k, (int, float)) or int(k) != k:
            raise RuntimeError(f'Cannot index array with string ({json.dumps(k)})')
        index = int(k)
        return v[index] if -len(v) <= index < len(v) else None
    if isinstance(v,str):
        if isinstance(k, bool) or not isinstance(k, (int, float)) or int(k) != k:
            raise RuntimeError(f'Cannot index string with number ({_short(k)})')
        index = int(k)
        return v[index] if -len(v) <= index < len(v) else None
    raise RuntimeError(f'Cannot index {_type_name(v)} with {_type_name(k)} ({json.dumps(k)})')
def _binary(op,left,right,value,env):
    if op==',': yield from _node(left,value,env); yield from _node(right,value,env); return
    if op=='|':
        for x in _node(left,value,env): yield from _node(right,x,env)
        return
    if op=='//':
        try: candidates = list(_node(left, value, env))
        except RuntimeError: candidates = []
        emitted = False
        for item in candidates:
            if _truth(item): emitted = True; yield item
        if not emitted: yield from _node(right, value, env)
        return
    if op in ('=', '|=', '+=', '-=', '*=', '/=', '%=', '//='):
        if op == '=' and left.operation == 'slice':
            for replacement in _node(right, value, env):
                yield _assign_slice(left, value, replacement, env)
            return
        paths = _paths(left, value, env)
        if op == '|=':
            result = value
            for path in sorted(paths, key=lambda path: tuple(
                    -part if isinstance(part, int) else part for part in path)):
                old = _get_path(result, path)
                outputs = list(_node(right, old, env))
                if outputs:
                    result = _set_path(result, path, outputs[0])
                else:
                    result = _delete_path(result, path)
            if paths: yield result
            return
        if op == '//=':
            result = value
            for path in sorted(paths, key=lambda path: tuple(
                    -part if isinstance(part, int) else part for part in path)):
                old = _get_path(result, path)
                if not _truth(old):
                    outputs = list(_node(right, value, env))
                    result = _set_path(result, path, outputs[0] if outputs else None)
            if paths: yield result
            return
        replacements = [None] if op == '|=' else list(_node(right, value, env))
        for replacement in replacements:
            result = value
            # Deleting array elements must not let an earlier deletion shift
            # the indices of later paths from the same path expression.
            ordered_paths = sorted(paths, key=lambda path: tuple(
                -part if isinstance(part, int) else part for part in path),
                reverse=False)
            for path in ordered_paths:
                old = _get_path(result, path)
                new = replacement if op in ('=',) else (_one(right, old, env) if op == '|=' else replacement)
                if op not in ('=', '|='):
                    new = _arithmetic(op[0], old, replacement)
                result = _set_path(result, path, new)
            if paths: yield result
        return
    ls=list(_node(left,value,env)); rs=list(_node(right,value,env))
    for x in ls:
      for y in rs:
        if op=='+':
            if x is None: yield y
            elif y is None: yield x
            elif isinstance(x, (int,float)) and isinstance(y, (int,float)): yield _numeric(x, y, '+')
            elif isinstance(x, str) and isinstance(y, str): yield x+y
            elif isinstance(x, list) and isinstance(y, list): yield x+y
            elif isinstance(x, dict) and isinstance(y, dict): yield {**x, **y}
            else: raise RuntimeError(f"{_type_name(x)} ({_short(x)}) and {_type_name(y)} ({_short(y)}) cannot be added")
        elif op=='-':
            if isinstance(x, list) and isinstance(y, list):
                yield [item for item in x if not any(_deep_equal(item, candidate) for candidate in y)]
                continue
            if not isinstance(x,(int,float)) or not isinstance(y,(int,float)):
                raise RuntimeError(f"{_type_name(x)} ({_short(x)}) and {_type_name(y)} ({_short(y)}) cannot be subtracted")
            yield _numeric(x, y, '-')
        elif op=='*':
            if isinstance(x, str) and isinstance(y, (int,float)):
                count = max(0, int(y))
                if len(x) * count > 100000000:
                    raise RuntimeError('Repeat string result too long')
                yield x * count
            elif isinstance(y, str) and isinstance(x, (int,float)):
                count = max(0, int(x))
                if len(y) * count > 100000000:
                    raise RuntimeError('Repeat string result too long')
                yield y * count
            elif isinstance(x, dict) and isinstance(y, dict):
                yield _merge_objects(x, y)
            else: yield _numeric(x, y, '*')
        elif op=='/':
            if y==0: raise RuntimeError(f"number ({_short(x)}) and number ({_short(y)}) cannot be divided because the divisor is zero")
            if isinstance(x,str) and isinstance(y,str): yield x.split(y)
            else: yield _numeric(x, y, '/')
        elif op=='%':
            if y==0: raise RuntimeError(f"number ({_short(x)}) and number ({_short(y)}) cannot be divided (remainder) because the divisor is zero")
            yield _numeric(x, y, '%')
        elif op in ('==','!=','<','>','<=','>='):
            if op in ('==', '!='):
                equal = _deep_equal(x, y)
                yield equal if op == '==' else not equal
            else:
                yield {'<':x<y,'>':x>y,'<=':x<=y,'>=':x>=y}[op]
        elif op in ('and','or'): yield (_truth(x) and _truth(y)) if op=='and' else (_truth(x) or _truth(y))
        else: yield x

def _arithmetic(op, left, right):
    if op == '+': return left + right
    if op == '-': return left - right
    if op == '*': return left * right
    if op == '/': return left / right
    if op == '%': return math.fmod(left, right)
    return right

def _numeric(left, right, op):
    """Apply jq's double arithmetic for values beyond exact integer range."""
    # jq 1.8 parses literals losslessly but arithmetic promotes them to a
    # double.  Keeping small integers as integers preserves compact output;
    # large values need the same rounding as jq's numeric operations.
    if any(isinstance(x, int) and not isinstance(x, bool) and abs(x) > 2**53 for x in (left, right)):
        left, right = float(left), float(right)
    if op == '+': return left + right
    if op == '-': return left - right
    if op == '*': return left * right
    if op == '/': return left / right
    return math.fmod(left, right)

def _merge_objects(left: dict, right: dict, depth: int = 0) -> dict:
    if depth > 10000: raise RuntimeError('Object merge too deep')
    root = dict(left)
    stack = [(root, right, depth)]
    while stack:
        target, source, level = stack.pop()
        if level > 10000: raise RuntimeError('Object merge too deep')
        for key, item in source.items():
            if key in target and isinstance(target[key], dict) and isinstance(item, dict):
                child = dict(target[key])
                target[key] = child
                stack.append((child, item, level + 1))
            else:
                target[key] = item
    return root


def _deep_equal(left: object, right: object, limit: int = 10000) -> bool:
    """Compare JSON values iteratively, preserving jq's deep-value guard."""
    pending: list[tuple[object, object, int]] = [(left, right, 0)]
    while pending:
        first, second, depth = pending.pop()
        if depth > limit:
            raise RuntimeError('Equality check too deep')
        if type(first) is not type(second):
            # jq treats integral and floating-point numbers as one number type.
            if isinstance(first, (int, float)) and not isinstance(first, bool) and isinstance(second, (int, float)) and not isinstance(second, bool):
                if first != second:
                    return False
                continue
            return False
        if isinstance(first, (dict, list)):
            if isinstance(first, list):
                if len(first) != len(second):
                    return False
                pending.extend((a, b, depth + 1) for a, b in zip(first, second))
            else:
                if first.keys() != second.keys():
                    return False
                pending.extend((first[key], second[key], depth + 1) for key in first)
            continue
        if isinstance(first, float) and math.isnan(first) and math.isnan(second):
            continue
        if first != second:
            return False
    return True


def _contains(haystack: object, wanted: object, limit: int = 10000) -> bool:
    """Implement containment with an explicit depth guard.

    jq deliberately turns excessively deep structural operations into a normal
    runtime error.  A Python call-stack overflow is not equivalent: it escapes
    jq's ``try`` handling and can also produce a traceback.  The inexpensive
    structural walk below detects the limit before the compatibility matcher
    runs, while retaining the ordinary jq containment rules for normal values.
    """
    pending: list[tuple[object, int]] = [(haystack, 0), (wanted, 0)]
    while pending:
        item, depth = pending.pop()
        if depth > limit:
            raise RuntimeError('Containment check too deep')
        if isinstance(item, list):
            pending.extend((child, depth + 1) for child in item)
        elif isinstance(item, dict):
            pending.extend((child, depth + 1) for child in item.values())

    def contained(left: object, right: object) -> bool:
        if isinstance(left, dict) and isinstance(right, dict):
            return all(k in left and contained(left[k], v) for k, v in right.items())
        if isinstance(left, list) and isinstance(right, list):
            return all(any(contained(item, candidate) for item in left) for candidate in right)
        if isinstance(left, str) and isinstance(right, str):
            return right in left
        return _deep_equal(left, right)

    try:
        return contained(haystack, wanted)
    except RecursionError as error:
        raise RuntimeError('Containment check too deep') from error


def _deep_json_dumps(value: object) -> str:
    """Encode deeply nested values without json.encoder's C recursion limit."""
    depth = 0
    probe = value
    while isinstance(probe, list) and len(probe) == 1:
        depth += 1
        probe = probe[0]
    if depth >= 10000:
        return json.dumps('<skipped: too deep>')
    pieces: list[str] = []
    stack: list[object] = [value]
    while stack:
        item = stack.pop()
        if isinstance(item, list):
            pieces.append('[')
            if item:
                stack.append(('close', ']'))
                for index in range(len(item) - 1, -1, -1):
                    if index < len(item) - 1:
                        stack.append(('raw', ','))
                    stack.append(item[index])
            else:
                pieces.append(']')
        elif isinstance(item, dict):
            pieces.append('{')
            entries = list(item.items())
            if entries:
                stack.append(('close', '}'))
                for index in range(len(entries) - 1, -1, -1):
                    key, child = entries[index]
                    if index < len(entries) - 1:
                        stack.append(('raw', ','))
                    stack.append(child)
                    stack.append(('raw', ':'))
                    stack.append(('raw', json.dumps(str(key), ensure_ascii=False)))
            else:
                pieces.append('}')
        elif isinstance(item, tuple) and item[0] == 'raw':
            pieces.append(item[1])
        elif isinstance(item, tuple) and item[0] == 'close':
            pieces.append(item[1])
        else:
            if isinstance(item, float) and not math.isfinite(item):
                pieces.append('null')
            else:
                pieces.append(json.dumps(item, separators=(',', ':'), ensure_ascii=False))
    return ''.join(pieces)


def _deep_json_loads(text: str) -> object:
    try:
        parsed = json.loads(text, parse_constant=lambda x: float('nan'))
        if parsed == '<skipped: too deep>':
            raise RuntimeError('Exceeds depth limit for parsing')
        return parsed
    except RecursionError:
        if text and set(text) <= {'[', ']'} and text.startswith('['):
            depth = text.count('[')
            value: object = []
            for _ in range(depth - 1):
                value = [value]
            return value
        raise

def _paths(node, value, env):
    op, args = node.operation, node.arguments
    # A comma in a path expression is a generator of independent paths.
    # This is especially important for del(.a, .b) and for path/index
    # functions whose argument is a comma expression.
    if op == 'binary' and args[0] == ',':
        return _paths(args[1], value, env) + _paths(args[2], value, env)
    if op == 'identity': return [()]
    if op == 'field': return [(args[0],)]
    if op == 'index': return [p + (args[1],) for p in _paths(args[0], value, env)]
    if op == 'indexexpr':
        result = []
        for p in _paths(args[0], value, env):
            current = _get_path(value, p)
            for key in _node(args[1], value, env):
                if isinstance(key, float) and math.isnan(key):
                    raise RuntimeError('Cannot set array element at NaN index')
                if isinstance(key, (dict, list)):
                    raise RuntimeError(f'Cannot index object with {_type_name(key)} ({_short(key)})')
                if isinstance(key, (int, float)) and not isinstance(key, bool) and int(key) >= 10000000:
                    raise RuntimeError('Array index too large')
                if isinstance(current, list) and isinstance(key, (int, float)):
                    if int(key) < 0 and abs(int(key)) > len(current): raise RuntimeError('Out of bounds negative array index')
                    if int(key) >= 10000000: raise RuntimeError('Array index too large')
                elif isinstance(key, (int, float)) and key < 0 and current is None:
                    raise RuntimeError('Out of bounds negative array index')
                result.append(p + (key,))
        return result
    if op == 'slice':
        result = []
        for p in _paths(args[0], value, env):
            current = _get_path(value, p)
            if not isinstance(current, (list, str)):
                continue
            start = _one(args[1], current, env)
            end = None if args[2] is None else _one(args[2], current, env)
            first = 0 if start is None or (isinstance(start, float) and math.isnan(start)) else math.floor(start)
            last = len(current) if end is None or (isinstance(end, float) and math.isnan(end)) else math.ceil(end)
            if first < 0: first = max(0, len(current) + int(first))
            if last < 0: last = max(0, len(current) + int(last))
            result.extend(p + (i,) for i in range(max(0, int(first)), min(len(current), int(last))))
        return result
    if op == 'iterate':
        result = []
        for p in _paths(args[0], value, env):
            current = _get_path(value, p)
            if isinstance(current, list): result.extend(p + (i,) for i in range(len(current)))
            elif isinstance(current, dict): result.extend(p + (k,) for k in current)
        return result
    if op == 'bind':
        return _paths(args[2], value, env)
    if op == 'binary' and args[0] == '|':
        result = []
        for p in _paths(args[1], value, env):
            current = _get_path(value, p)
            result.extend(p + tail for tail in _paths(args[2], current, env))
        return result
    if op == 'call' and not args[1] and (args[0], 0) in env.get('__funcs__', {}):
        function = env['__funcs__'][(args[0], 0)]
        closure_env = dict(env)
        if len(function) > 2:
            closure_env['__funcs__'] = function[2]
        return _paths(function[1], value, closure_env)
    if op == 'call' and not args[1] and args[0] in env:
        bound = env[args[0]]
        if isinstance(bound, tuple) and bound and bound[0] == '__closure__':
            return _paths(bound[1], value, bound[2])
    if op == 'call' and args[0] == 'select' and args[1]:
        return [()] if _truth(_one(args[1][0], value, env)) else []
    if op == 'call' and not args[1] and args[0] == 'last':
        return [(-1,)]
    return []

def _assign_slice(node, value, replacement, env):
    base_node, start_node, end_node = node.arguments
    result = value
    for parent in _paths(base_node, value, env):
        current = _get_path(result, parent)
        if not isinstance(current, (list, str)):
            continue
        start = _one(start_node, current, env)
        end = None if end_node is None else _one(end_node, current, env)
        first = 0 if start is None or (isinstance(start, float) and math.isnan(start)) else math.floor(start)
        last = len(current) if end is None or (isinstance(end, float) and math.isnan(end)) else math.ceil(end)
        if isinstance(current, str):
            raise RuntimeError('Cannot update string slices')
        updated = list(current)
        updated[int(first):int(last)] = replacement if isinstance(replacement, list) else [replacement]
        result = _set_path(result, parent, updated)
    return result

def _validate_path_key(container: object, key: object, *, updating: bool) -> None:
    if isinstance(container, list):
        if isinstance(key, bool) or not isinstance(key, (int, float)) or (isinstance(key, float) and math.isnan(key)):
            message = 'Cannot set array element at NaN index' if updating and isinstance(key, float) and math.isnan(key) else 'Cannot update field at array index of array'
            raise RuntimeError(message)
    elif isinstance(container, dict) and not isinstance(key, str):
        raise RuntimeError(f'Cannot index object with {_type_name(key)} ({_short(key)})')


def _get_path_checked(value, path):
    current = value
    for key in path:
        _validate_path_key(current, key, updating=False)
        if isinstance(current, dict): current = current.get(key)
        elif isinstance(current, list):
            index = int(key); current = current[index] if -len(current) <= index < len(current) else None
"""Application-facing interpreter orchestration."""

import json
from collections.abc import Iterable, Iterator

from .evaluator import evaluate
from .parser import parse
from .runtime import JsonValue


class Interpreter:
    """Compile once, then evaluate each JSON input in order."""

    def __init__(self, program: str) -> None:
        self._compiled = parse(program)

    def run(self, inputs: Iterable[JsonValue]) -> Iterator[JsonValue]:
        """Yield every output, preserving input and generator ordering."""
        for value in inputs:
            yield from evaluate(self._compiled, value)


def parse_input(line: str) -> JsonValue:
    """Decode one JSON input value."""
    return json.loads(line.lstrip("\ufeff"), parse_constant=_parse_json_constant)


def parse_inputs(text: str) -> Iterator[JsonValue]:
    """Decode every whitespace-separated JSON value in an input stream.

    ``jq`` accepts JSON values separated by arbitrary whitespace, so a value may
    span multiple physical lines.  ``raw_decode`` preserves the boundary
    between successive values without requiring a non-standard JSON parser.
    """
    # jq accepts its non-standard constants in lower case as well.  The
    # standard decoder only dispatches parse_constant for JSON's capitalized
    # spellings, so normalize standalone bare constants before decoding.
    import re
    text = re.sub(r'(?<![A-Za-z_])-(?:nan|infinite)(?![A-Za-z_])', lambda m: '-NaN' if 'nan' in m.group(0) else '-Infinity', text)
    text = re.sub(r'(?<![A-Za-z_])(?:nan|infinite)(?![A-Za-z_])', lambda m: 'NaN' if m.group(0) == 'nan' else 'Infinity', text)
    decoder = json.JSONDecoder(parse_constant=_parse_json_constant)
    position = 0
    while True:
        while position < len(text) and text[position].isspace():
            position += 1
        if position >= len(text):
            return
        if position == 0 and text.startswith("\ufeff"):
            position += 1
            continue
        value, position = decoder.raw_decode(text, position)
        yield value


def _parse_json_constant(value: str) -> float:
    """Decode jq's accepted non-standard numeric constants."""
    return {"NaN": float("nan"), "nan": float("nan"),
            "Infinity": float("inf"), "infinite": float("inf"),
            "-Infinity": float("-inf"), "-infinite": float("-inf"),
            "-NaN": float("nan"), "-nan": float("nan")} [value]
"""Syntax tree types shared by the lexer, parser, and evaluator."""

from dataclasses import dataclass


@dataclass(frozen=True)
class Filter:
    """Base type for compiled jq filters."""


@dataclass(frozen=True)
class Identity(Filter):
    """The ``.`` filter, yielding its input unchanged."""


@dataclass(frozen=True)
class Iterate(Filter):
    """The ``.[]`` filter, yielding array or object members in order."""


@dataclass(frozen=True)
class Literal(Filter):
    """A JSON literal filter."""

    value: object


@dataclass(frozen=True)
class Comma(Filter):
    """Concatenate the output streams of two filters."""

    left: Filter
    right: Filter


@dataclass(frozen=True)
class Raise(Filter):
    """Raise a jq runtime error when evaluated."""

    message: str = "error"


@dataclass(frozen=True)
class Array(Filter):
    """Collect a filter's generated values into an array."""

    expression: Filter


@dataclass(frozen=True)
class Limit(Filter):
    """Keep at most ``count`` values from a filter stream."""

    count: int
    expression: Filter

@dataclass(frozen=True)
class Pipe(Filter):
    left: Filter
    right: Filter

@dataclass(frozen=True)
class StringTemplate(Filter):
    parts: tuple[str | Filter, ...]

@dataclass(frozen=True)
class Format(Filter):
    name: str
    template: StringTemplate | None = None

@dataclass(frozen=True)
class Add(Filter):
    left: Filter
    right: Filter

@dataclass(frozen=True)
class Node(Filter):
    """General expression node used by the complete source parser."""
    operation: str
    arguments: tuple[object, ...] = ()

#!/usr/bin/env python3
"""Run the upstream jq conformance corpus against a candidate implementation.

This is the scoring instrument. It is supplied, not authored: it is staged verbatim into the
build directory, hash-verified against the import, and restored before grading. Its exit status
is the acceptance verdict.

It is deliberately external to the implementation. Upstream jq grades itself, through its own
``--run-tests`` flag; a self-graded suite proves nothing here, so this runner re-implements the
corpus protocol and drives the candidate as a subprocess, one process per case.

Imported sources land in ``sources/`` inside the application directory, so this is normally
invoked as ``python3 sources/run_conformance.py`` from that directory.

Usage:
    JQ=./jq python3 sources/run_conformance.py                     # full corpus, the scored run
    JQ=./jq python3 sources/run_conformance.py -v                  # list passing cases too
    JQ=./jq python3 sources/run_conformance.py --json              # machine-readable report
    JQ=./jq python3 sources/run_conformance.py --list              # print cases, run nothing
    JQ=./jq python3 sources/run_conformance.py --select 'reduce'   # develop one construct

Environment:
    JQ         command that runs the candidate. Required -- this harness is language-neutral
               and deliberately has no default implementation language.

Exit codes:
    0   every case that ran passed
    1   at least one case failed or errored
    2   the harness could not run: bad usage, missing corpus, or a stale exclusion
"""

from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import subprocess
import sys
from dataclasses import dataclass, field
from pathlib import Path

HERE = Path(__file__).resolve().parent
CORPUS = HERE / "jq.test"
EXCLUSIONS = HERE / "exclusions.txt"

#: A case that has not produced output in this long is not going to. jq's own suite runs the
#: whole corpus in under a second; anything near this bound is a runaway generator.
DEFAULT_TIMEOUT = 10.0

PASS, FAIL, ERROR, SKIP = "pass", "fail", "error", "skip"

#: jq's documented exit codes, which this kit's interface contract adopts. The distinction is
#: load-bearing: the corpus's %%FAIL cases are programs that must not compile, while an ordinary
#: case may legitimately raise at run time part-way through its output and still be correct.
EXIT_COMPILE_ERROR = 3
EXIT_RUNTIME_ERROR = 5


def split_lines(text: str) -> list[str]:
    """Split on newlines only.

    ``str.splitlines`` is Unicode-aware and also breaks on U+000B, U+000C, U+0085, U+2028, and
    U+2029. The corpus contains cases whose expected output embeds those code points inside JSON
    strings -- ``trim, ltrim, rtrim`` over the Unicode whitespace set is one -- and splitting
    there shreds one JSON value into several, failing a correct implementation.
    """
    lines = text.split("\n")
    if lines and lines[-1] == "":
        lines.pop()
    return lines


@dataclass
class Case:
    """One corpus case: a program, an input, and what it must produce.

    ``expect_failure`` cases are the corpus's ``%%FAIL`` blocks. Upstream compares their
    diagnostic text; this runner requires only that the candidate reject the program. The
    expected strings are jq's exact C-implementation diagnostics, down to the caret art
    underlining the offending token -- reproducing them is reverse-engineering an
    implementation, not conforming to a specification. The text is parsed and reported so a
    reader can see what upstream said, and is never compared.
    """

    line: int
    program: str
    stdin: str = ""
    expected: list[str] = field(default_factory=list)
    expect_failure: bool = False
    diagnostic: str = ""


@dataclass
class Result:
    case: Case
    status: str
    detail: str = ""
    actual: list[str] = field(default_factory=list)
    return_code: int | None = None
    stderr: str = ""


class HarnessError(Exception):
    """A fault in the kit or its invocation, never a fault in the candidate."""


# --------------------------------------------------------------------------------------------
# Corpus parsing
# --------------------------------------------------------------------------------------------


def parse_corpus(text: str) -> list[Case]:
    """Parse the jq test corpus.

    The format is documented in the corpus's own header: cases are groups of lines separated by
    blank lines; blank lines and lines starting with ``#`` are ignored. A case is a program
    line, an input line, and then zero or more expected output lines. A case preceded by a
    ``%%FAIL`` or ``%%FAIL IGNORE MSG`` marker is a program line followed by the diagnostic
    upstream jq emits, which may itself span several lines of source excerpt and caret art.
    """
    cases: list[Case] = []
    block: list[tuple[int, str]] = []
    expect_failure = False
    lines = split_lines(text)

    def flush() -> None:
        nonlocal block, expect_failure
        if block:
            cases.append(_case_from_block(block, expect_failure))
        block = []
        expect_failure = False

    for number, raw in enumerate(lines, start=1):
        stripped = raw.strip()
        if not stripped:
            flush()
            continue
        if raw.startswith("%%FAIL"):
            flush()
            expect_failure = True
            continue
        # A '#' comment closes nothing: upstream places section banners between cases, always
        # with blank lines around them, and never inside a case.
        if raw.lstrip().startswith("#") and not block:
            continue
        if raw.lstrip().startswith("#"):
            continue
        block.append((number, raw))
    flush()
    return cases


def _case_from_block(block: list[tuple[int, str]], expect_failure: bool) -> Case:
    line, program = block[0]
    if expect_failure:
        diagnostic = "\n".join(text for _, text in block[1:])
        return Case(line=line, program=program, expect_failure=True, diagnostic=diagnostic)
    if len(block) < 2:
        raise HarnessError(
            f"{CORPUS.name}:{line}: case has a program but no input line; the corpus is malformed"
        )
    return Case(
        line=line,
        program=program,
        stdin=block[1][1],
        expected=[text for _, text in block[2:]],
    )


# --------------------------------------------------------------------------------------------
# Exclusions
# --------------------------------------------------------------------------------------------


def parse_exclusions(path: Path) -> list[str]:
    """Read the declared exclusions: one verbatim program line per entry, ``#`` for reasons."""
    if not path.is_file():
        return []
    return [
        line
        for line in split_lines(path.read_text(encoding="utf-8"))
        if line.strip() and not line.lstrip().startswith("#")
    ]


def apply_exclusions(cases: list[Case], exclusions: list[str]) -> set[int]:
    """Return the corpus line numbers of excluded cases.

    An exclusion that matches nothing is a hard error rather than a shrug. The corpus is pinned
    by hash, so a stale exclusion means the pin moved without the exclusion list being revisited
    -- and a silent no-op there would quietly re-admit a case the kit cannot run.
    """
    by_program: dict[str, list[Case]] = {}
    for case in cases:
        by_program.setdefault(case.program, []).append(case)

    excluded: set[int] = set()
    stale: list[str] = []
    for program in exclusions:
        matched = by_program.get(program)
        if not matched:
            stale.append(program)
            continue
        excluded.update(case.line for case in matched)
    if stale:
        listed = "\n".join(f"    {program}" for program in stale)
        raise HarnessError(
            f"{EXCLUSIONS.name}: these exclusions match no case in {CORPUS.name}:\n{listed}\n"
            "The corpus and the exclusion list have drifted apart."
        )
    return excluded


# --------------------------------------------------------------------------------------------
# Comparison
# --------------------------------------------------------------------------------------------


def jv_equal(left: object, right: object) -> bool:
    """Compare two decoded JSON values the way jq's own ``jv_equal`` does.

    Structural, not textual: ``1`` and ``1.0`` are the same jq value and the corpus relies on
    that. Python's ``==`` almost does this, but it also equates ``True`` with ``1`` and
    ``False`` with ``0``, which jq does not; booleans are therefore matched by identity of type
    before anything else.
    """
    if isinstance(left, bool) or isinstance(right, bool):
        return isinstance(left, bool) and isinstance(right, bool) and left is right
    if isinstance(left, (int, float)) and isinstance(right, (int, float)):
        return left == right
    if isinstance(left, list) and isinstance(right, list):
        return len(left) == len(right) and all(jv_equal(a, b) for a, b in zip(left, right))
    if isinstance(left, dict) and isinstance(right, dict):
        return left.keys() == right.keys() and all(jv_equal(left[k], right[k]) for k in left)
    if type(left) is not type(right):
        return False
    return left == right


def _decode(line: str) -> tuple[bool, object]:
    try:
        return True, json.loads(line)
    except ValueError:
        return False, line


def outputs_match(expected: list[str], actual: list[str]) -> bool:
    if len(expected) != len(actual):
        return False
    for want, got in zip(expected, actual):
        want_ok, want_value = _decode(want)
        got_ok, got_value = _decode(got)
        if want_ok and got_ok:
            if not jv_equal(want_value, got_value):
                return False
        elif want.strip() != got.strip():
            return False
    return True
